solution:
def has_loop(escalates_to, start):
    slow = fast = start
    while fast is not None and escalates_to[fast] is not None:
        slow = escalates_to[slow]
        fast = escalates_to[escalates_to[fast]]
        if slow == fast:
            return True
    return False
